<?php
namespace App\Console\Commands;
use App\Models\DocumentoVersion; use Illuminate\Console\Command; use Illuminate\Support\Facades\Storage;
class DiagnosticarDocumentos extends Command { protected $signature='documentos:diagnosticar'; protected $description='Informa inconsistencias documentales sin modificarlas.'; public function handle():int{$d=Storage::disk('local');$r=DocumentoVersion::pluck('ruta_archivo')->all();$a=$h=$i=0;foreach(DocumentoVersion::cursor() as $v){if(!$d->exists($v->ruta_archivo)){$a++;$this->line("AUSENTE {$v->id}");continue;}if(hash_file('sha256',$d->path($v->ruta_archivo))!==$v->hash_sha256){$h++;$this->line("HASH_ALTERADO {$v->id}");}if(!str_starts_with($v->ruta_archivo,"documentos/{$v->organizacion_id}/{$v->copropiedad_id}/{$v->documento_id}/")){$i++;$this->line("METADATO_INCONSISTENTE {$v->id}");}}$x=collect($d->allFiles('documentos'))->reject(fn($p)=>str_starts_with($p,'documentos/staging/'))->reject(fn($p)=>in_array($p,$r,true));foreach($x as $p)$this->line("HUERFANO {$p}");$this->info("Ausentes: {$a}; Alterados: {$h}; Huérfanos: {$x->count()}; Inconsistentes: {$i}");return self::SUCCESS;}}
